import { chromium } from '../../tools/prototype-capture/node_modules/playwright/index.mjs'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const scriptDir = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(scriptDir, '..')
const outDir = path.join(root, 'screenshots', '0803-workflow-audit')
const base = process.env.AUDIT_BASE || 'http://127.0.0.1:4173'
const report = { startedAt: new Date().toISOString(), base, checks: [], errors: [] }

fs.mkdirSync(outDir, { recursive: true })

async function launchBrowser() {
  const candidates = [
    'C:/Program Files/Google/Chrome/Application/chrome.exe',
    'C:/Program Files/Microsoft/Edge/Application/msedge.exe',
  ]
  for (const executablePath of candidates) {
    if (fs.existsSync(executablePath)) return chromium.launch({ headless: true, executablePath })
  }
  return chromium.launch({ headless: true })
}

function check(name, passed, detail) {
  report.checks.push({ name, passed, detail })
  process.stdout.write(`[${passed ? 'PASS' : 'FAIL'}] ${name}: ${detail}\n`)
  if (!passed) process.exitCode = 1
}

async function goto(page, route) {
  await page.goto(`${base}${route}`, { waitUntil: 'networkidle', timeout: 30000 })
}

async function login(page) {
  await goto(page, '/login')
  await page.getByRole('button', { name: /演示全权限账户/ }).click()
  await page.waitForURL(/dashboard/, { timeout: 15000 })
}

async function screenshot(page, name) {
  const target = path.join(outDir, `${name}.png`)
  await page.screenshot({ path: target, fullPage: false, animations: 'disabled' })
  return path.relative(root, target).replace(/\\/g, '/')
}

const browser = await launchBrowser()
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const page = await context.newPage()
page.on('pageerror', (error) => report.errors.push(`pageerror: ${error.message}`))
page.on('console', (message) => {
  if (message.type() === 'error') report.errors.push(`console: ${message.text()}`)
})

try {
  await login(page)

  const routes = [
    ['/reserve/history', '历年储量成果'],
    ['/reserve/evaluation', '储量评估与管理'],
    ['/planning/history', '历史生产数据'],
    ['/planning/compile/workflow', '数据规划工作流'],
    ['/planning/compile/discovery-scheduling', '待发现排产'],
    ['/planning/compile/data-entry', '数据入库'],
    ['/assistant', '智能辅助工作台'],
  ]
  for (const [route, title] of routes) {
    await goto(page, route)
    const visible = await page.getByRole('heading', { name: title, exact: true }).isVisible()
    check(`route ${route}`, visible, title)
  }

  await goto(page, '/reserve/version?source=audit')
  check('legacy reserve redirect', page.url().includes('/reserve/evaluation') && page.url().includes('legacy=1'), page.url())
  await goto(page, '/planning/workbook?source=audit')
  check('legacy planning redirect', page.url().includes('/planning/compile/workflow') && page.url().includes('legacy=1'), page.url())

  await goto(page, '/reserve/evaluation')
  await page.getByRole('button', { name: '完成本步并继续' }).click()
  check('reserve blocker gate', await page.getByRole('heading', { name: '四张独立采集表' }).isVisible(), '阻断未修复时停留在采集步骤')
  await page.getByRole('button', { name: '模拟补齐阻断项' }).click()
  await page.getByRole('button', { name: '填写预警说明' }).click()
  await page.getByRole('button', { name: '完成本步并继续' }).click()
  check('reserve advance after resolution', await page.getByRole('heading', { name: '储量汇总目录' }).isVisible(), '修复阻断并说明预警后进入汇总')

  await goto(page, '/planning/compile/workflow')
  await page.getByRole('button', { name: '修复闭合差额' }).click()
  await page.getByRole('button', { name: '填写预警说明' }).click()
  await page.getByRole('button', { name: '完成本步并继续' }).click()
  check('planning summary boundary', await page.getByText('石油汇总表：11—17').isVisible(), '石油汇总边界正确')

  for (const width of [1440, 1280, 1024]) {
    await page.setViewportSize({ width, height: 900 })
    for (const [key, route] of [['reserve', '/reserve/evaluation?step=analysis'], ['planning', '/planning/compile/workflow?step=analysis']]) {
      await goto(page, route)
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth)
      const file = await screenshot(page, `${key}-${width}`)
      check(`${key} ${width}px overflow`, overflow <= 1, `${file}; horizontal overflow=${overflow}px`)
    }
  }

  check('browser console', report.errors.length === 0, report.errors.length ? report.errors.join(' | ') : 'no pageerror/console error')
} finally {
  await browser.close()
  report.finishedAt = new Date().toISOString()
  fs.writeFileSync(path.join(outDir, 'report.json'), `${JSON.stringify(report, null, 2)}\n`, 'utf8')
}

